} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  const toggle = this.elements.parentMenu.elements.submenuToggles.find(
    t => t.elements.controlledMenu === this
  );
  if (toggle) {
    toggle.close();
    toggle.dom.toggle.focus();
  }
}
